style.css:
@-moz-document domain("unmatched.gg") {
/* ============ ПАЛИТРА ============ */
    :root, html.dark {
        --accent: 80 92% 55% !important;             /* #a3e635 — лайм gamesense */
        --accent-dark: 80 92% 42% !important;
        --accent-foreground: 0 0% 4% !important;
        --ring: 80 92% 55% !important;

        --background: 0 0% 5% !important;
        --card: 0 0% 7% !important;
        --popover: 0 0% 10% !important;
        --secondary: 0 0% 11% !important;
        --muted: 0 0% 16% !important;
        --muted-foreground: 0 0% 55% !important;
        --border: 0 0% 14% !important;
        --input: 0 0% 11% !important;
        --foreground: 0 0% 96% !important;
        --card-foreground: 0 0% 96% !important;
        --popover-foreground: 0 0% 96% !important;
        --dark-popover-foreground: 0 0% 96% !important;
    }

    /* ============ БАЗА ============ */
    html, body, body.bg {
        background: #080808 !important;
        background-image: none !important;
        color: #f0f0f0 !important;
    }

    /* Тонкая сетка/шум на фоне для «глубины» (опционально, можно удалить) */
    body::before {
        content: "";
        position: fixed;
        inset: 0;
        pointer-events: none;
        z-index: 0;
        background:
            radial-gradient(ellipse at top, hsl(80 92% 55% / 0.04), transparent 60%),
            radial-gradient(ellipse at bottom right, hsl(80 92% 55% / 0.03), transparent 55%);
    }
    #root { position: relative; z-index: 1; }

    /* ============ ХЕДЕР — стеклянный, с зелёной линией ============ */
    header {
        background: rgba(8, 8, 8, 0.85) !important;
        background-image: none !important;
        backdrop-filter: blur(14px) saturate(140%);
        -webkit-backdrop-filter: blur(14px) saturate(140%);
        border-bottom: 1px solid hsl(80 92% 55% / 0.18) !important;
        box-shadow: 0 1px 0 hsl(80 92% 55% / 0.08), 0 8px 24px -12px rgba(0,0,0,0.8) !important;
    }

    /* ============ ФУТЕР ============ */
    footer {
        background: #080808 !important;
        background-image: none !important;
        border-top: 1px solid #1c1c1c !important;
    }

    /* ============ ЛОГОТИП «gg» — мягкое свечение ============ */
    #logo-text .text-accent,
    #width-pulse-3910 {
        color: hsl(80 92% 60%) !important;
        text-shadow:
            0 0 6px hsl(80 92% 55% / 0.7),
            0 0 18px hsl(80 92% 55% / 0.35) !important;
    }

    /* ============ КАРТОЧКИ — глубина, тонкие границы ============ */
    .rounded-xl.bg-card\/80,
    #lobby,
    #friendlist {
        background: linear-gradient(180deg, #0e0e0e 0%, #0a0a0a 100%) !important;
        border: 1px solid #1e1e1e !important;
        box-shadow:
            inset 0 1px 0 rgba(255,255,255,0.03),
            0 4px 20px -8px rgba(0,0,0,0.9) !important;
    }

    /* Заголовки карточек (Чат, Live, Discord, Онлайн) */
    .rounded-xl.bg-card\/80 > div:first-child,
    #friendlist > div:first-child,
    [class*="border-b"][class*="border-white\/5"] {
        background: #0d0d0d !important;
        border-bottom: 1px solid #1a1a1a !important;
    }

    /* Внутренние панели */
    [class*="bg-secondary\/30"],
    [class*="bg-secondary\/20"],
    [class*="bg-secondary\/10"],
    [class*="bg-secondary\/50"] {
        background-color: #101010 !important;
    }

    /* Тонкие границы */
    [class*="border-white\/5"],
    [class*="border-white\/10"] {
        border-color: #1c1c1c !important;
    }

    /* ============ ЧАТ ============ */
    /* Ховер сообщения */
    .group.hover\:bg-secondary\/30:hover {
        background-color: #151515 !important;
    }
    /* Текст сообщений — чуть ярче */
    .dont-break-out {
        color: #d8d8d8 !important;
    }
    /* Двоеточие после ника */
    .group .text-muted-foreground {
        color: #4a4a4a !important;
    }

    /* ============ ПОЛЯ ВВОДА ============ */
    input, textarea, select, [role="combobox"] {
        background-color: #101010 !important;
        border: 1px solid #222 !important;
        color: #f0f0f0 !important;
        transition: border-color .15s, box-shadow .15s;
    }
    input:focus, textarea:focus, [role="combobox"]:focus,
    input:focus-visible, textarea:focus-visible {
        border-color: hsl(80 92% 55% / 0.55) !important;
        box-shadow: 0 0 0 3px hsl(80 92% 55% / 0.12) !important;
        outline: none !important;
    }
    input::placeholder, textarea::placeholder {
        color: #555 !important;
    }

    /* Кнопка отправки в чате — зелёная с glow */
    button[type="submit"].w-10.h-10,
    form button[type="submit"] {
        box-shadow: 0 0 14px -3px hsl(80 92% 55% / 0.7) !important;
    }

    /* ============ ТАБЫ (Друзья / Публичные лобби, Live / Трансляции) ============ */
    [role="tablist"] {
        background-color: #0d0d0d !important;
        border: 1px solid #1c1c1c !important;
        border-radius: 8px !important;
    }
    [role="tab"][data-state="active"] {
        background-color: hsl(80 92% 55%) !important;
        color: #0a0a0a !important;
        box-shadow: 0 0 14px -3px hsl(80 92% 55% / 0.7) !important;
        font-weight: 600;
    }
    [role="tab"][data-state="inactive"] {
        color: #888 !important;
    }

    /* ============ LIVE-ИНДИКАТОР ============ */
    .animate-ping, .bg-accent {
        background-color: hsl(80 92% 55%) !important;
    }
    .bg-green-500 { background-color: hsl(80 92% 55%) !important; }

    /* ============ КАРТОЧКИ МАТЧЕЙ — hover ============ */
    a[href^="/match/"] {
        border: 1px solid #1c1c1c !important;
        background-color: #101010 !important;
        transition: all .18s ease !important;
    }
    a[href^="/match/"]:hover {
        border-color: hsl(80 92% 55% / 0.6) !important;
        box-shadow:
            0 0 0 1px hsl(80 92% 55% / 0.35),
            0 0 28px -6px hsl(80 92% 55% / 0.55) !important;
        transform: translateY(-1px);
    }

    /* ============ ССЫЛКИ И НАВИГАЦИЯ ============ */
    nav a, header a {
        transition: color .15s, text-shadow .15s !important;
    }
    nav a:hover, header a:hover,
    .hover\:text-accent:hover {
        color: hsl(80 92% 60%) !important;
    }

    /* Активная ссылка (Главная) — с glow */
    a.text-accent, a[aria-current="page"] {
        color: hsl(80 92% 60%) !important;
        text-shadow: 0 0 10px hsl(80 92% 55% / 0.55) !important;
    }

    /* ============ КНОПКА «ПРЕМИУМ» ============ */
    a[href="/premium/purchase"] button {
        background: hsl(80 92% 55%) !important;
        color: #0a0a0a !important;
        font-weight: 700 !important;
        box-shadow: 0 0 18px -4px hsl(80 92% 55% / 0.7) !important;
    }
    a[href="/premium/purchase"] button:hover {
        filter: brightness(1.08) !important;
        box-shadow: 0 0 26px -4px hsl(80 92% 55% / 0.95) !important;
    }

    /* ============ КНОПКА PLAY (в лобби) ============ */
    #lobby button.bg-accent,
    #lobby button[class*="bg-accent"] {
        background-color: hsl(80 92% 55%) !important;
        color: #0a0a0a !important;
        box-shadow: 0 0 20px -4px hsl(80 92% 55% / 0.8) !important;
        transition: all .18s !important;
    }
    #lobby button.bg-accent:hover {
        box-shadow: 0 0 30px -2px hsl(80 92% 55% / 1) !important;
        transform: scale(1.05);
    }

    /* ============ ПАГИНАЦИЯ ============ */
    nav[aria-label="pagination"] a {
        border-color: #1c1c1c !important;
        transition: all .15s !important;
    }
    nav[aria-label="pagination"] a[aria-current="page"] {
        border-color: hsl(80 92% 55%) !important;
        color: hsl(80 92% 60%) !important;
        box-shadow: 0 0 12px -3px hsl(80 92% 55% / 0.6) !important;
    }
    nav[aria-label="pagination"] a:hover {
        border-color: hsl(80 92% 55% / 0.5) !important;
        color: hsl(80 92% 60%) !important;
    }

    /* ============ СКРОЛЛБАР ============ */
    ::-webkit-scrollbar { width: 8px; height: 8px; }
    ::-webkit-scrollbar-track { background: transparent; }
    ::-webkit-scrollbar-thumb {
        background: #222;
        border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: hsl(80 92% 55% / 0.55);
    }

    /* ============ МОБИЛЬНОЕ МЕНЮ ============ */
    nav.fixed.bg-card {
        background-color: #0d0d0d !important;
        border-color: #1c1c1c !important;
        box-shadow: 4px 0 24px -8px rgba(0,0,0,0.9) !important;
    }

    /* ============ РАЗДЕЛИТЕЛИ ВНУТРИ ПАНЕЛЕЙ ============ */
    [data-orientation="horizontal"][role="none"],
    [data-orientation="vertical"][role="none"] {
        background-color: #1c1c1c !important;
    }

    /* ============ СТАТУС-ТОЧКА «LIVE» НА КАРТОЧКЕ ============ */
    span.bg-accent\/90,
    [class*="bg-accent\/90"] {
        background-color: hsl(80 92% 55% / 0.9) !important;
    }

    /* ============ DISCORD — В ЦВЕТ САЙТА ============ */

/* Кнопка "Перейти в Discord" */
a[href*="discord"] button,
a[href*="discord.com"] button,
a[href*="discord.gg"] button {
    background: hsl(80 92% 55%) !important;
    background-color: hsl(80 92% 55%) !important;
    color: #0a0a0a !important;
    border-color: hsl(80 92% 55%) !important;

    box-shadow:
        0 0 14px -3px hsl(80 92% 55% / 0.65) !important;

    transition: all .18s ease !important;
}

/* Текст и иконка Discord внутри кнопки */
a[href*="discord"] button *,
a[href*="discord.com"] button *,
a[href*="discord.gg"] button * {
    color: #0a0a0a !important;
}

/* Если иконка сделана через SVG */
a[href*="discord"] button svg,
a[href*="discord.com"] button svg,
a[href*="discord.gg"] button svg {
    color: #0a0a0a !important;
    fill: currentColor !important;
}

/* Hover */
a[href*="discord"] button:hover,
a[href*="discord.com"] button:hover,
a[href*="discord.gg"] button:hover {
    background: hsl(80 92% 60%) !important;
    box-shadow:
        0 0 24px -3px hsl(80 92% 55% / 0.9) !important;
    transform: translateY(-1px);
}

/* Синяя Discord-иконка в заголовке карточки */
a[href*="discord"] svg,
[class*="discord"] svg,
[class*="Discord"] svg {
    color: hsl(80 92% 55%) !important;
}

/* Для SVG, использующих fill */
[class*="discord"] svg path,
[class*="Discord"] svg path {
    fill: currentColor !important;
}
}
